Below is a reusable Terraform module for the requested S3, PostgreSQL RDS, and IAM service-account role. It supports isolated dev/prod deployments through separate state keys and `tfvars`, including production S3 cross-region replication.

> This module covers the three resources requested. EKS and HTTPS exposure from the broader canonical scenario should be separate modules; this module accepts EKS OIDC details so its IAM role can be used through IRSA.

## Directory structure

```text
terraform/
├── modules/
│   └── app-support/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── versions.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
├── backend-dev.hcl
├── backend-prod.hcl
├── main.tf
├── variables.tf
├── outputs.tf
└── versions.tf
```

---

## `modules/app-support/versions.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = "~> 5.0"
      configuration_aliases = [aws.replica]
    }
  }
}
```

## `modules/app-support/variables.tf`

```hcl
variable "name" {
  description = "Application name used in resource names."
  type        = string
}

variable "environment" {
  description = "Deployment environment."
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "bucket_name" {
  description = "Globally unique primary S3 bucket name."
  type        = string
}

variable "replica_bucket_name" {
  description = "Globally unique replica bucket name. Required when replication is enabled."
  type        = string
  default     = null
}

variable "enable_replication" {
  description = "Enable cross-region S3 replication."
  type        = bool
  default     = false
}

variable "vpc_id" {
  description = "VPC in which RDS is deployed."
  type        = string
}

variable "private_subnet_ids" {
  description = "Private subnet IDs for the RDS subnet group."
  type        = list(string)

  validation {
    condition     = length(var.private_subnet_ids) >= 2
    error_message = "At least two private subnet IDs are required."
  }
}

variable "database_ingress_security_group_ids" {
  description = "Security groups allowed to connect to PostgreSQL."
  type        = list(string)
  default     = []
}

variable "database_ingress_cidr_blocks" {
  description = "Private CIDRs allowed to connect to PostgreSQL."
  type        = list(string)
  default     = []
}

variable "db_name" {
  description = "Initial PostgreSQL database name."
  type        = string
  default     = "app"
}

variable "db_username" {
  description = "PostgreSQL master username. Password is managed by RDS in Secrets Manager."
  type        = string
  default     = "app_admin"
}

variable "db_engine_version" {
  description = "PostgreSQL engine version."
  type        = string
  default     = "16.3"
}

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
}

variable "db_allocated_storage" {
  description = "Initial RDS storage in GiB."
  type        = number
  default     = 20
}

variable "db_max_allocated_storage" {
  description = "Maximum autoscaled RDS storage in GiB."
  type        = number
  default     = 100
}

variable "db_multi_az" {
  description = "Whether RDS is deployed as Multi-AZ."
  type        = bool
  default     = false
}

variable "db_storage_encrypted" {
  description = "Whether RDS storage is encrypted."
  type        = bool
  default     = true
}

variable "db_backup_retention_period" {
  description = "RDS backup retention in days."
  type        = number
  default     = 7

  validation {
    condition     = var.db_backup_retention_period >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

variable "oidc_provider_arn" {
  description = "EKS OIDC provider ARN used for IRSA."
  type        = string
}

variable "oidc_provider_url" {
  description = "EKS OIDC issuer URL, for example https://oidc.eks.us-east-1.amazonaws.com/id/..."
  type        = string
}

variable "kubernetes_namespace" {
  description = "Namespace containing the application service account."
  type        = string
  default     = "app"
}

variable "kubernetes_service_account" {
  description = "Kubernetes service account allowed to assume the IAM role."
  type        = string
  default     = "app"
}

variable "tags" {
  description = "Additional resource tags."
  type        = map(string)
  default     = {}
}
```

## `modules/app-support/main.tf`

```hcl
locals {
  resource_name = "${var.name}-${var.environment}"

  tags = merge(var.tags, {
    Application = var.name
    Environment = var.environment
    ManagedBy   = "Terraform"
  })

  oidc_provider_host = trimsuffix(
    trimprefix(var.oidc_provider_url, "https://"),
    "/"
  )
}

# -----------------------------------------------------------------------------
# Primary application-assets bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "assets" {
  bucket = var.bucket_name
  tags   = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "assets" {
  bucket = aws_s3_bucket.assets.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.assets.arn,
          "${aws_s3_bucket.assets.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Optional production replica bucket in the aliased replica region
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = var.replica_bucket_name
  tags   = local.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = var.replica_bucket_name != null
      error_message = "replica_bucket_name is required when replication is enabled."
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica[0].arn,
          "${aws_s3_bucket.replica[0].arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# S3 replication role and configuration
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "replication_assume_role" {
  count = var.enable_replication ? 1 : 0

  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0

  name               = "${local.resource_name}-s3-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json
  tags               = local.tags
}

data "aws_iam_policy_document" "replication" {
  count = var.enable_replication ? 1 : 0

  statement {
    sid = "ReadSourceBucketConfiguration"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ReadSourceObjectVersions"

    actions = [
      "s3:GetObjectVersion",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionTagging"
    ]

    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid = "WriteReplicaObjects"

    actions = [
      "s3:ReplicateDelete",
      "s3:ReplicateObject",
      "s3:ReplicateTags"
    ]

    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_replication ? 1 : 0

  name   = "${local.resource_name}-s3-replication"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-to-secondary-region"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.assets,
    aws_s3_bucket_versioning.replica
  ]
}

# -----------------------------------------------------------------------------
# PostgreSQL RDS
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "this" {
  name       = "${local.resource_name}-db"
  subnet_ids = var.private_subnet_ids
  tags       = local.tags
}

resource "aws_security_group" "database" {
  name        = "${local.resource_name}-database"
  description = "PostgreSQL access for ${local.resource_name}"
  vpc_id      = var.vpc_id

  tags = merge(local.tags, {
    Name = "${local.resource_name}-database"
  })
}

resource "aws_vpc_security_group_ingress_rule" "database_sg" {
  for_each = toset(var.database_ingress_security_group_ids)

  security_group_id            = aws_security_group.database.id
  referenced_security_group_id = each.value
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432
  description                  = "PostgreSQL from application security group"
}

resource "aws_vpc_security_group_ingress_rule" "database_cidr" {
  for_each = toset(var.database_ingress_cidr_blocks)

  security_group_id = aws_security_group.database.id
  cidr_ipv4         = each.value
  ip_protocol       = "tcp"
  from_port         = 5432
  to_port           = 5432
  description       = "PostgreSQL from approved private CIDR"
}

resource "aws_vpc_security_group_egress_rule" "database" {
  security_group_id = aws_security_group.database.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
  description       = "Database response traffic"
}

resource "aws_db_instance" "postgres" {
  identifier = "${local.resource_name}-postgres"

  engine         = "postgres"
  engine_version = var.db_engine_version
  instance_class = var.db_instance_class

  allocated_storage     = var.db_allocated_storage
  max_allocated_storage = var.db_max_allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = var.db_storage_encrypted

  db_name  = var.db_name
  username = var.db_username

  # AWS generates the password and stores it encrypted in Secrets Manager.
  # No database password is committed to Git or passed through tfvars.
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.database.id]

  publicly_accessible = false
  multi_az            = var.db_multi_az
  deletion_protection = true
  skip_final_snapshot = false

  final_snapshot_identifier = "${local.resource_name}-postgres-final"

  backup_retention_period = var.db_backup_retention_period
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  auto_minor_version_upgrade = true
  copy_tags_to_snapshot       = true
  apply_immediately           = var.environment == "dev"

  performance_insights_enabled = var.environment == "prod"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# IAM role for Kubernetes service account (IRSA)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "service_account_assume_role" {
  statement {
    sid     = "AllowServiceAccount"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_provider_host}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_provider_host}:sub"
      values = [
        "system:serviceaccount:${var.kubernetes_namespace}:${var.kubernetes_service_account}"
      ]
    }
  }
}

resource "aws_iam_role" "service_account" {
  name                 = "${local.resource_name}-service-account"
  assume_role_policy   = data.aws_iam_policy_document.service_account_assume_role.json
  max_session_duration = 3600
  tags                 = local.tags
}

data "aws_iam_policy_document" "service_account" {
  statement {
    sid = "ListApplicationBucket"

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ManageApplicationObjects"

    actions = [
      "s3:AbortMultipartUpload",
      "s3:DeleteObject",
      "s3:GetObject",
      "s3:ListMultipartUploadParts",
      "s3:PutObject"
    ]

    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid = "ReadDatabaseMasterSecret"

    actions = [
      "secretsmanager:DescribeSecret",
      "secretsmanager:GetSecretValue"
    ]

    resources = [
      aws_db_instance.postgres.master_user_secret[0].secret_arn
    ]
  }
}

resource "aws_iam_role_policy" "service_account" {
  name   = "${local.resource_name}-application"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.service_account.json
}
```

## `modules/app-support/outputs.tf`

```hcl
output "bucket_name" {
  description = "Primary application-assets bucket name."
  value       = aws_s3_bucket.assets.id
}

output "bucket_arn" {
  description = "Primary application-assets bucket ARN."
  value       = aws_s3_bucket.assets.arn
}

output "replica_bucket_name" {
  description = "Replica bucket name, if enabled."
  value       = try(aws_s3_bucket.replica[0].id, null)
}

output "database_address" {
  description = "RDS PostgreSQL hostname."
  value       = aws_db_instance.postgres.address
}

output "database_port" {
  description = "RDS PostgreSQL port."
  value       = aws_db_instance.postgres.port
}

output "database_name" {
  description = "Initial PostgreSQL database name."
  value       = aws_db_instance.postgres.db_name
}

output "database_security_group_id" {
  description = "RDS security group ID."
  value       = aws_security_group.database.id
}

output "database_master_secret_arn" {
  description = "Secrets Manager ARN containing the RDS-generated master credentials."
  value       = aws_db_instance.postgres.master_user_secret[0].secret_arn
}

output "service_account_role_arn" {
  description = "IAM role ARN for the Kubernetes service account."
  value       = aws_iam_role.service_account.arn
}
```

