## `main.tf`

```hcl
provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region

  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

module "app_support" {
  source = "./modules/app-support"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  name        = var.name
  environment = var.environment

  bucket_name         = var.bucket_name
  enable_replication  = var.enable_replication
  replica_bucket_name = var.replica_bucket_name

  vpc_id            = var.vpc_id
  private_subnet_ids = var.private_subnet_ids

  database_ingress_security_group_ids = var.database_ingress_security_group_ids
  database_ingress_cidr_blocks        = var.database_ingress_cidr_blocks

  db_instance_class    = var.db_instance_class
  db_multi_az          = var.db_multi_az
  db_storage_encrypted = var.db_storage_encrypted

  oidc_provider_arn          = var.oidc_provider_arn
  oidc_provider_url          = var.oidc_provider_url
  kubernetes_namespace       = var.kubernetes_namespace
  kubernetes_service_account = var.kubernetes_service_account
}
```

